import { GetObjectCommand, ListObjectsV2Command, S3Client } from '@aws-sdk/client-s3';
import { Upload } from '@aws-sdk/lib-storage';

export const putDocument = (document, Bucket, Key) =>
    new Upload({ client: new S3Client({ region: 'us-east-1' }), params: { Body: document, Bucket, Key } });

export const getDocument = async <T>(Bucket: string, Key: string): Promise<T> => {
    const client = new S3Client({});
    const { Body } = await client.send(new GetObjectCommand({ Bucket, Key }));
    return JSON.parse(await Body.transformToString()) as T;
};

/**
 * Every object key under a prefix, folder placeholders excluded.
 */
export const listKeys = async (Bucket: string, Prefix?: string): Promise<Array<string>> => {
    const client = new S3Client({});
    const keys: Array<string> = [];
    let ContinuationToken: string | undefined;
    do {
        // eslint-disable-next-line no-await-in-loop
        const response = await client.send(new ListObjectsV2Command({ Bucket, Prefix, ContinuationToken }));
        (response.Contents ?? []).forEach(({ Key }) => {
            if (Key && !Key.endsWith('/')) {
                keys.push(Key);
            }
        });
        ContinuationToken = response.IsTruncated ? response.NextContinuationToken : undefined;
    } while (ContinuationToken);
    return keys.sort();
};

/**
 * Reads every json document stored under a prefix. Documents that cannot be
 * read or parsed are skipped rather than failing the whole listing, a single
 * bad object in a bucket shouldn't stop a metering sweep.
 */
export const listDocuments = async <T>(Bucket: string, Prefix?: string): Promise<Array<T>> => {
    const keys = await listKeys(Bucket, Prefix);
    const documents = await Promise.all(
        keys.map(async (Key) => {
            try {
                return await getDocument<T>(Bucket, Key);
            } catch (e) {
                return undefined;
            }
        }),
    );
    return documents.filter((document) => document) as Array<T>;
};
