import { Logger } from '@nestjs/common';
import { getDocument, listDocuments } from '../../utils/aws/s3.js';

/**
 * An AWS account a business has handed us for measurement.
 */
export class MeteredAccount {
    /**
     * The account the metering role lives in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * The role we assume to read the account.
     * @example "arn:aws:iam::445566778899:role/metering-metering"
     */
    public roleArn: string;
    /**
     * The external id the role's trust policy asks for, when it asks for one.
     */
    public externalId?: string;
    /**
     * The region the business runs the metered workload in.
     * @example "us-east-1"
     */
    public region: string;
}

/**
 * One account a customer has been onboarded onto.
 */
export class OnboardedAccount {
    /**
     * The account the customer runs in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * Set when the account holds nothing but this customer's workload. A
     * dedicated account has exactly one tenant, so everything measured inside
     * it belongs to that customer whatever the resource tags claim.
     */
    public dedicated?: boolean;
}

/**
 * The per customer onboarding record kept in the business' metering bucket, one
 * object per customer under {@link MeteringRegistry.customerRecordPrefix}. A
 * customer is only billable for an account it has a record for.
 */
export class CustomerOnboardingRecord {
    private static readonly logger = new Logger(CustomerOnboardingRecord.name);
    public customerId: string;
    public displayName?: string;
    public accounts: Array<OnboardedAccount>;

    /**
     * Reads every onboarding record sitting under the prefix. Objects that are
     * not onboarding records are ignored.
     */
    static async loadAll(bucket: string, prefix?: string): Promise<Array<CustomerOnboardingRecord>> {
        const documents = await listDocuments<CustomerOnboardingRecord>(bucket, prefix);
        const records = documents.filter((document) => document?.customerId && Array.isArray(document?.accounts));
        CustomerOnboardingRecord.logger.log(
            `Loaded ${records.length} customer onboarding records from ${bucket}/${prefix ?? ''}`,
        );
        return records;
    }
}

/**
 * Who is allowed to be billed for what a sweep finds in an account.
 */
export class AccountTenancy {
    private static readonly logger = new Logger(AccountTenancy.name);
    /**
     * Customers onboarded for the account, in a stable order.
     */
    public tenants: Array<string> = [];
    /**
     * The single customer the account is dedicated to, when it is dedicated to
     * one.
     */
    public dedicatedTo?: string;
}

/**
 * The tenancy of every account a business has onboarded customers onto, built
 * from the per customer onboarding records.
 */
export class MeteringTenancy {
    private static readonly logger = new Logger(MeteringTenancy.name);
    private readonly accounts: Map<string, AccountTenancy> = new Map();

    static fromCustomerRecords(records: Array<CustomerOnboardingRecord>): MeteringTenancy {
        const tenancy = new MeteringTenancy();
        const dedicatedClaims: Map<string, Array<string>> = new Map();
        records.forEach(({ customerId, accounts }) => {
            (accounts ?? []).forEach((onboarded) => {
                const accountId = onboarded?.accountId;
                if (!accountId || !customerId) {
                    return;
                }
                const account = tenancy.accounts.get(accountId) ?? new AccountTenancy();
                if (!account.tenants.includes(customerId)) {
                    account.tenants.push(customerId);
                }
                if (onboarded.dedicated) {
                    dedicatedClaims.set(accountId, (dedicatedClaims.get(accountId) ?? []).concat(customerId));
                }
                tenancy.accounts.set(accountId, account);
            });
        });
        dedicatedClaims.forEach((claimants, accountId) => {
            const account = tenancy.accounts.get(accountId);
            if (claimants.length === 1) {
                account.dedicatedTo = claimants[0];
            } else {
                // Two customers cannot both have the account to themselves, so
                // the account is treated as shared and the tags decide.
                MeteringTenancy.logger.warn(
                    `Account ${accountId} is claimed as dedicated by more than one customer, treating it as shared`,
                    claimants.sort().join(','),
                );
            }
        });
        return tenancy;
    }

    tenantsFor(accountId: string): Array<string> {
        return this.accounts.get(accountId)?.tenants ?? [];
    }

    dedicatedCustomerFor(accountId: string): string | undefined {
        return this.accounts.get(accountId)?.dedicatedTo;
    }

    /**
     * The customers a metered resource's usage has to be split between.
     *
     * A resource living in an account dedicated to a single customer belongs to
     * that customer no matter which customer its tags name, tags included when
     * they name nobody at all. Anywhere else the tags are a claim that is only
     * honoured for customers genuinely onboarded for the account, and usage no
     * onboarded customer can be tied to belongs to nobody.
     */
    ownersOf(accountId: string, taggedCustomerIds?: string): Array<string> {
        const dedicatedTo = this.dedicatedCustomerFor(accountId);
        if (dedicatedTo) {
            return [dedicatedTo];
        }
        const tenants = this.tenantsFor(accountId);
        const claimed = (taggedCustomerIds ?? '')
            .split(',')
            .map((customerId) => customerId.trim())
            .filter((customerId) => customerId);
        const owners = claimed.filter((customerId, index) => tenants.includes(customerId) && claimed.indexOf(customerId) === index);
        return owners;
    }
}

/**
 * The onboarding record a business keeps in its metering bucket. It is written
 * by the onboarding flow and read by every collector that has to sweep more
 * than one account.
 */
export class MeteringRegistry {
    public businessID: string;
    /**
     * Key prefix the per customer onboarding records sit under in the same
     * bucket, one object per customer.
     * @example "onboarding/customers/"
     */
    public customerRecordPrefix: string;
    public accounts: Array<MeteredAccount>;

    static async load(bucket: string, key: string): Promise<MeteringRegistry> {
        return getDocument<MeteringRegistry>(bucket, key);
    }

    /**
     * The tenancy of the accounts in this registry, read from the per customer
     * onboarding records kept beside it in the same bucket.
     */
    static async loadTenancy(registry: MeteringRegistry, bucket: string): Promise<MeteringTenancy> {
        const records = await CustomerOnboardingRecord.loadAll(bucket, registry?.customerRecordPrefix);
        return MeteringTenancy.fromCustomerRecords(records);
    }
}
