        { customerId: 'cus_b', accounts: [{ accountId: '222222222222' }] },
    ];

    const sweep = (instancesByAccount: Record<string, Array<unknown>>) => {
        (getDocument as jest.Mock).mockResolvedValue(registry);
        (listDocuments as jest.Mock).mockResolvedValue(customerRecords);
        (getInstanceWithFilters as jest.Mock).mockImplementation((region, creds) => []);
        (getInstanceWithFilters as jest.Mock).mockImplementation(() => []);
        let call = 0;
        (getInstanceWithFilters as jest.Mock).mockImplementation(() => {
            const accountId = registry.accounts[call]?.accountId;
            call += 1;
            return Promise.resolve(instancesByAccount[accountId] ?? []);
        });
