        });
        expect(results.map(({ customerId }) => customerId)).toEqual(['cus_a', 'cus_b']);
        results.forEach(({ recordValue }) => expect(recordValue).toBeCloseTo(HOUR_FRACTION / 2, 8));
    });

    it('bills a single tenant tag on a shared account in full', async () => {
        const results = await sweep({
            '222222222222': [instance('i-9', { meteringDimensionId: 'dim-1', meteringCustomerId: 'cus_b' })],
        });
        expect(results).toHaveLength(1);
        expect(results[0].customerId).toEqual('cus_b');
        expect(results[0].recordValue).toBeCloseTo(HOUR_FRACTION, 8);
    });

    it('leaves unplaceable shared account usage off the bill', async () => {
        const results = await sweep({
            '222222222222': [
                instance('i-9', { meteringDimensionId: 'dim-1' }),
                instance('i-10', { meteringDimensionId: 'dim-1', meteringCustomerId: '' }),
            ],
        });
        expect(results).toEqual([]);
    });

    it('leaves usage tagged for customers not onboarded for the account off the bill', async () => {
        const results = await sweep({
            '222222222222': [
                instance('i-9', { meteringDimensionId: 'dim-1', meteringCustomerId: 'cus_unknown' }),
                instance('i-10', { meteringDimensionId: 'dim-1', meteringCustomerId: ' cus_b , cus_unknown ' }),
            ],
        });
        expect(results).toHaveLength(1);
        expect(results[0].customerId).toEqual('cus_b');
        expect(results[0].recordValue).toBeCloseTo(HOUR_FRACTION, 8);
        expect(results[0].metadata.instanceIds).toEqual('i-10');
    });
